// Exercise the pointer overload: template <typename T, typename Fn>
// void immer::for_each_chunk(const T* first, const T* last, Fn&& fn)
// We build a byte buffer and pick a valid [first,last) subrange inside it.
std::string buf = FUZZ_PARAM_STR();
const unsigned char* base = reinterpret_cast<const unsigned char*>(buf.data());
size_t n = buf.size();
if (n > 4096) { FUZZ_BAIL(); } // defensive, keep buffers small for perf
// Choose [a,b] within [0,n]. Allow a==b for empty range.
unsigned int ri = *FUZZ_PARAM(unsigned int);
unsigned int rj = *FUZZ_PARAM(unsigned int);
size_t a = (n == 0) ? 0 : (ri % (n + 1));
size_t b = (n == 0) ? 0 : (rj % (n + 1));
if (a > b) { size_t t = a; a = b; b = t; }
const unsigned char* first = base + a;
const unsigned char* last  = base + b;
// fn must accept (const T*, const T*). Assert basic properties and touch data.
auto fn = [&](const unsigned char* f, const unsigned char* l) {
    FUZZ_ASSERT(f <= l, "chunk pointers must be ordered");
    FUZZ_ASSERT(f >= base && f <= base + n, "first within buffer bounds");
    FUZZ_ASSERT(l >= base && l <= base + n, "last within buffer bounds");
    size_t len = static_cast<size_t>(l - f);
    if (len) {
        volatile unsigned char sink = 0; // avoid optimizing away reads
        sink ^= f[0];
        sink ^= f[len - 1];
        (void)sink;
    }
};
immer::for_each_chunk(first, last, fn);
// No persistent objects to return.

// Exercise the pointer predicate overload: template <typename T, typename Fn>
// bool immer::for_each_chunk_p(const T* first, const T* last, Fn&& fn)
std::string buf = FUZZ_PARAM_STR();
const unsigned char* base = reinterpret_cast<const unsigned char*>(buf.data());
size_t n = buf.size();
if (n > 4096) { FUZZ_BAIL(); }
unsigned int ri = *FUZZ_PARAM(unsigned int);
unsigned int rj = *FUZZ_PARAM(unsigned int);
size_t a = (n == 0) ? 0 : (ri % (n + 1));
size_t b = (n == 0) ? 0 : (rj % (n + 1));
if (a > b) { size_t t = a; a = b; b = t; }
const unsigned char* first = base + a;
const unsigned char* last  = base + b;
unsigned int behavior = *FUZZ_PARAM(unsigned int); // steer predicate return
auto fn = [&](const unsigned char* f, const unsigned char* l) -> bool {
    FUZZ_ASSERT(f <= l, "chunk pointers must be ordered");
    FUZZ_ASSERT(f >= base && f <= base + n, "first within buffer bounds");
    FUZZ_ASSERT(l >= base && l <= base + n, "last within buffer bounds");
    size_t len = static_cast<size_t>(l - f);
    // Return false sometimes to exercise the boolean path (though for pointer
    // overload there's only one call). Prefer false when len>0 and bit set.
    bool want_stop = ((behavior & 1u) != 0u) && (len > 0);
    if (len) {
        volatile unsigned char sink = f[0] ^ f[len ? (len - 1) : 0];
        (void)sink;
    }
    return !want_stop; // true to continue, false to stop
};
bool ok = immer::for_each_chunk_p(first, last, fn);
(void)ok;
