// Exercise immer::get_table_key with a concrete type that provides a public `id`.
// We validate that the returned key equals the object's `id`.
struct SGetKey {
    long long id;
    int payload; // extra field to avoid trivial struct optimizations
};
SGetKey v{ .id = (long long)(*FUZZ_PARAM(unsigned long long)), .payload = (int)(*FUZZ_PARAM(unsigned int)) };
// Call the target function and assert the key matches
auto key = immer::get_table_key(v);
FUZZ_ASSERT(key == v.id, "get_table_key must return x.id");
// No persistent objects to return; this stub only validates behavior.

// Exercise immer::set_table_key with a concrete type that provides assignable `id`.
