    long long id;
    char padding[8];
};
SSetKey v{ .id = (long long)(*FUZZ_PARAM(unsigned long long)), .padding = {0} };
long long new_key = (long long)(*FUZZ_PARAM(unsigned long long));
// Call the target function
auto v2 = immer::set_table_key(v, new_key);
// Validate properties: v2.id updated to new_key
FUZZ_ASSERT(v2.id == new_key, "set_table_key must set x.id to k");
