// Use the stateless functor to extract and set keys via its forwarding operators.
// We keep `keyfn` alive by returning it as an output.
struct Elem {
    unsigned id;
    int data;
};
Elem e{ .id = (unsigned)(*FUZZ_PARAM(unsigned int)), .data = (int)(*FUZZ_PARAM(unsigned int)) };
// 1) Extract key via unary operator()(x)
auto k1 = (*keyfn)(e);
FUZZ_ASSERT(k1 == e.id, "table_key_fn()(x) must forward to get_table_key(x)");
// 2) Set key via binary operator()(x, k)
unsigned new_k = (unsigned)(*FUZZ_PARAM(unsigned int));
auto e2 = (*keyfn)(e, new_k);
FUZZ_ASSERT(e2.id == new_k, "table_key_fn()(x,k) must forward to set_table_key(x,k)");
