// No inputs are required.

// Allocate; must not be null per fuzzer contract.
immer::table_key_fn *keyfn = new immer::table_key_fn();

// Basic validation/coverage: exercise both operator() overloads using a
// simple type that provides a public `id` member as required by get_table_key/set_table_key.
struct Elem {
    unsigned long long id;
    int payload;
};
Elem e{ .id = (unsigned long long)(*FUZZ_PARAM(unsigned long long)), .payload = (int)(*FUZZ_PARAM(unsigned int)) };

// Extract key via unary call; must equal e.id
